import asyncio

sem = asyncio.Semaphore(10)

async def call_llm(prompt: str) -> str:
    async with sem:
        for attempt in range(3):
            try:
                resp = await asyncio.wait_for(
                    client.chat.completions.create(
                        model="gpt-4o",
                        messages=[{"role": "user", "content": prompt}],
                    ),
                    timeout=30,          # per-call deadline
                )
                return resp.choices[0].message.content
            except (asyncio.TimeoutError, RateLimitError):
                if attempt == 2:
                    raise               # permanent failure after 3 tries
                await asyncio.sleep(2 ** attempt)  # 1s, 2s backoff

async def main(prompts: list[str]) -> list[str]:
    # tolerate individual failures; don't lose 49 for 1
    return await asyncio.gather(
        *[call_llm(p) for p in prompts],
        return_exceptions=True,
    )

results = asyncio.run(asyncio.wait_for(main(prompts), timeout=600))
# failures arrive as exception objects in-place — inspect & handle
